import{_ as i}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as s}from"./chunks/CrystalBall.BdqnOTQQ.js";import{_ as t,a,b as r,c as l,d as n,e as o,f as p,g as u,h as d,i as c,j as m,k as b}from"./chunks/M-S-PS2c2.DvbnSuBF.js";import{_ as v}from"./chunks/M-S-PS5b.B4zocwby.js";import{_ as f,o as g,c as h,a3 as y}from"./chunks/framework.g9mfNVRQ.js";const T=JSON.parse('{"title":"Simulation prédictive","description":"","frontmatter":{"source_hash":"74f3d09e63","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/use/predictions.md","filePath":"fr/use/predictions.md"}'),_={name:"fr/use/predictions.md"};function x(q,e,z,L,P,k){return g(),h("div",null,[...e[0]||(e[0]=[y('<div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Paramètres<br>  <img src="'+s+'" style="width:5%;"> Simulations prédictives</p></div><p>Les paramètres de simulation prédictive de xDrip sont une fonction expérimentale, non approuvée médicalement. Relisez bien le <a href="./../install/install.html#understand-what-is-xdrip">CLUF</a> avant de l&#39;activer. Ne vous en servez pas pour prendre des décisions médicales.</p><div class="warning custom-block"><p class="custom-block-title">Attention</p><p>Si vous utilisez un système en boucle fermée, ne vous fiez pas à ces prédictions, car elles ne tiennent pas compte de la modulation du débit basal.</p></div><div class="admonition xdripitem"><p class="admonition-title">xDrip+ Simulations prédictives</p><p> Afficher les simulations mathématiques basées sur les données de profil et les logs de glucides/insuline</p></div><p>Activer les prédictions ajoute la courbe de prédiction violet clair sur le graphique principal. Cette courbe vous montre comment votre glycémie devrait théoriquement évoluer en fonction de l&#39;insuline et des glucides saisis dans xDrip. Plus de détails sur l&#39;affichage <a href="./display.html#treatments-and-predictions-curves">ici</a>.</p><img src="'+t+'" style="zoom:75%;"><p>xDrip peut gérer plusieurs types d&#39;insuline. Voir <a href="#multiple-insulin-types">ci-dessous</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Types d&#39;insuline multiples</p><p> Options pour utiliser plusieurs types d&#39;insuline</p></div><h3 id="carb-ratio-and-insulin-sensitivity" tabindex="-1">Ratio de glucides et sensibilité à l&#39;insuline <a class="header-anchor" href="#carb-ratio-and-insulin-sensitivity" aria-label="Permalink to &quot;Ratio de glucides et sensibilité à l&#39;insuline {#carb-ratio-and-insulin-sensitivity}&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Import automatique</p><p>Si vous utilisez <a href="./interapp.html#receiving-from-nsclient">Accepter les traitements</a> depuis AAPS ou NSClient, ces paramètres et le profil basal sont importés automatiquement lors d&#39;un changement de profil.</p></div><p>Ces paramètres sont essentiels à la gestion du diabète et doivent être connus.<br> Ils varient très probablement au cours de la journée et doivent être calculés pour chaque repas, ainsi qu&#39;en dehors des repas.<br> Chacun a ses propres paramètres. N&#39;utilisez pas ceux de quelqu&#39;un d&#39;autre.</p><p>Le ratio de glucides est la quantité de glucides couverte par 1 unité d&#39;insuline.</p><p>Par exemple, 10 signifie que chaque tranche de 10 g de glucides nécessite 1 unité d&#39;insuline.</p><div class="admonition xdripitem"><p class="admonition-title">Ratio de Glucides</p><p> Ratio insuline:glucides 1u pour X grammes de glucides</p></div><p>La sensibilité à l&#39;insuline est la baisse de glycémie obtenue avec une unité d&#39;insuline, sans glucides dans le sang.</p><p>Par exemple, 50 (ou 2,8) signifie qu&#39;1 unité fait baisser la glycémie de 50 mg/dl (ou 2,8 mmol/l).</p><div class="admonition xdripitem"><p class="admonition-title">Sensibilité à l&#39;Insuline</p><p> Baisse de la glycémie pour 1 Unité</p></div><h3 id="carb-absorbtion-rate" tabindex="-1">Taux d&#39;absorption des glucides <a class="header-anchor" href="#carb-absorbtion-rate" aria-label="Permalink to &quot;Taux d&#39;absorption des glucides {#carb-absorbtion-rate}&quot;">​</a></h3><p>Le taux d&#39;absorption des glucides est la vitesse à laquelle votre organisme assimile les glucides. Voir <a href="https://diyps.org/2014/05/29/determining-your-carbohydrate-absorption-rate-diyps-lessons-learned/" target="_blank" rel="noreferrer">ici</a> comment calculer ce paramètre.</p><div class="admonition xdripitem"><p class="admonition-title">Taux d&#39;absorption de glucides</p><p> Glucides linéaires absorbés par heure</p></div><p>Appuyer sur l&#39;un des deux menus ci-dessus ouvre l&#39;éditeur de profil de traitement.</p><img src="'+a+'" style="zoom:75%;"><p>Vous pouvez définir les glucides par unité d&#39;insuline et le facteur de correction : pensez simplement à valider chaque saisie et à ne pas passer d&#39;une ligne à l&#39;autre sans l&#39;avoir confirmée. Enregistrez une fois terminé.</p><img src="'+r+'" style="zoom:75%;"><p>Vous allez créer des blocs pour différentes heures de la journée.<br> Pour créer (scinder) ou supprimer un bloc, faites un appui long sur la partie supérieure du bloc.</p><img src="'+l+'" style="zoom:75%;"><p>Appuyer sur la barre horaire en haut d&#39;un bloc permet de la modifier ; la modification se répercute aussi sur le bloc en dessous.<br> Vous finirez par obtenir quelque chose comme ceci.</p><img src="'+n+'" style="zoom:75%;"><p>Si nécessaire, vous pouvez appliquer une modification globale en pourcentage à tous les paramètres avec le curseur du bas.<br> N&#39;oubliez pas d&#39;enregistrer.</p><img src="'+o+'" style="zoom:75%;"><h3 id="basal-profile-editor" tabindex="-1">Éditeur de profil Basal <a class="header-anchor" href="#basal-profile-editor" aria-label="Permalink to &quot;Éditeur de profil Basal {#basal-profile-editor}&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Cette fonction est en cours de développement.</p><p>Le profil basal actuel est importé automatiquement depuis NSClient lorsque <a href="./interapp.html#receiving-from-nsclient">Accepter les traitements</a> est activé.</p></div><div class="admonition xdripitem"><p class="admonition-title">Éditeur de profil Basal</p><p> Éditeur graphique pour les profils basal de la pompe</p></div><p>Vous pouvez afficher et modifier votre profil basal.</p><ol><li>Sélectionnez le profil à modifier ou à afficher</li><li>Exporter (pas encore fonctionnel)</li><li>Enregistrer localement</li></ol><img src="'+p+'" style="zoom:78%;"><p>Pour modifier votre profil basal :</p><ol><li>Appuyez sur la barre horaire du basal à modifier : elle devient orange</li><li>Changez le pas si nécessaire</li><li>Utilisez la case numérotée positive ou la flèche vers le haut pour augmenter</li><li>Utilisez la case numérotée négative ou la flèche vers le bas pour diminuer</li><li>Utilisez set, ou appuyez deux fois sur la barre, pour appliquer la nouvelle valeur</li></ol><img src="'+u+'" style="zoom:78%;"><h3 id="use-trend-momentum" tabindex="-1">Utiliser la tendance dynamique <a class="header-anchor" href="#use-trend-momentum" aria-label="Permalink to &quot;Utiliser la tendance dynamique {#use-trend-momentum}&quot;">​</a></h3><p>La tendance dynamique est indépendante des prédictions : c&#39;est simplement une extrapolation mathématique de votre tendance glycémique actuelle (hausse/baisse/stable), c&#39;est-à-dire : si la glycémie continue d&#39;évoluer selon sa tendance, sans tenir compte de l&#39;insuline et des glucides, où ira-t-elle ? Elle peut être utilisée pour les <a href="./alarms.html#forecasted-low-alert">alarmes de prévision de bas</a>.</p><p>La tendance dynamique peut être intégrée aux prédictions (recommandé).</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser la tendance dynamique</p><p> Calculer y compris la tendance de glycémie</p></div><p>Inclure la tendance actuelle (1) peut éviter des variations brusques de la prédiction et se rapprocher davantage de l&#39;évolution réelle (2).</p><img src="'+d+'" style="zoom:75%;"><img src="'+v+'" style="zoom:75%;"><img src="'+c+'" style="zoom:75%;"><h3 id="eula" tabindex="-1">CLUF <a class="header-anchor" href="#eula" aria-label="Permalink to &quot;CLUF {#eula}&quot;">​</a></h3><p>Relisez le <a href="./../install/install.html#understand-what-is-xdrip">CLUF</a> avant d&#39;utiliser cette fonction.</p><div class="admonition xdripitem"><p class="admonition-title">Contrat de licence de l&#39;utilisateur final</p><p> Non destiné à l&#39;usage médical - outil de recherche uniquement</p></div><h3 id="low-level-prediction" tabindex="-1">Prédiction bas niveau <a class="header-anchor" href="#low-level-prediction" aria-label="Permalink to &quot;Prédiction bas niveau {#low-level-prediction}&quot;">​</a></h3><p>Vous pouvez configurer ici d&#39;autres paramètres de prédiction.</p><div class="admonition xdripitem"><p class="admonition-title">Valeurs de niveau de prédiction d&#39;hypoglycémie</p><p> Paramètres avancés pour les algorithmes</p></div><p>La cible est utilisée par le calculateur de bolus. C&#39;est la glycémie cible souhaitée.</p><p>La <a href="https://www.diabettech.com/insulin/why-we-are-regularly-wrong-in-the-duration-of-insulin-action-dia-times-we-use-and-why-it-matters/" target="_blank" rel="noreferrer">durée d&#39;action</a> de l&#39;insuline dépend de votre type d&#39;insuline. Modifier cette valeur nécessite de redémarrer xDrip (ou le téléphone).</p><p>La glycémie cible est la valeur utilisée pour calculer les corrections suggérées.</p><div class="admonition xdripitem"><p class="admonition-title">Glycémie cible par défaut</p><p> 100 / 5.6</p></div><p>La durée d&#39;action de l&#39;insuline est un paramètre à discuter avec votre diabétologue. Avec un système en boucle fermée, cette valeur sera bien plus élevée. N&#39;oubliez pas cependant que les prédictions de xDrip sont surtout utiles en multi-injections, pas avec une pompe.</p><div class="admonition xdripitem"><p class="admonition-title">Durée de l&#39;insuline en heures</p><p> 3</p></div><p>Les paramètres hépatiques ont été introduits pour tenir compte de la réaction du glycogène hépatique aux hypoglycémies, mais ils sont difficiles à caractériser et doivent rester à leurs valeurs par défaut.</p><div class="admonition xdripitem"><p class="admonition-title">Ratio de sensibilité du foie par défaut</p><p> 2</p></div><div class="admonition xdripitem"><p class="admonition-title">Impact maximum sur le foie par défaut (0-1)</p><p> 0.8</p></div><h3 id="multiple-insulin-types" tabindex="-1">Types d&#39;insuline multiples <a class="header-anchor" href="#multiple-insulin-types" aria-label="Permalink to &quot;Types d&#39;insuline multiples {#multiple-insulin-types}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Types d&#39;insuline multiples</p></div><p>Sélectionnez les types d&#39;insuline que vous utilisez.</p><p>Vous pouvez sélectionner jusqu&#39;à trois types d&#39;insuline, puis choisir celui utilisé pour le basal et celui utilisé pour le bolus.</p><div class="admonition xdripitem"><p class="admonition-title">Editeur de profil de traitement</p><p>Activer au moins un et maximum trois profils.<br>  ☐ FIASP (ultra-fast acting)<br>  ☐ Afrezza (ultra-fast acting)<br>  ☐ Apidra (ultra-fast acting)<br>  ☐ Novorapid (fast acting)<br>  ☐ Humalog (fast acting)<br>  ☐ Lispro (fast acting)<br>  ☐ Actrapid (short acting)<br>  ☐ Insulatard (NPH)<br>  ☐ Toujeo (long acting)<br>  ☐ Lantus (long acting)<br>  ☐ Levemir (long acting)<br>  ☐ Basaglar (long acting)<br>  ☐ Tresiba (ultra-long acting)</p></div><p>Dans la partie inférieure de la boîte de dialogue, sélectionnez l&#39;insuline utilisée pour le basal (action lente) et pour le bolus (action rapide) :</p><div class="admonition xdripitem"><p class="admonition-title">Choisir le profil d&#39;insuline basale.</p></div><div class="admonition xdripitem"><p class="admonition-title">Choisir le profil d&#39;insuline de bolus. Également utilisé pour la pompe et le stylo...</p></div><p>Une fois terminé, enregistrez vos choix.</p><div class="admonition xdripitem"><p class="admonition-title"><span style="background-color:grey;color:white;">  ANNULER </span>  <span style="background-color:grey;color:white;">  RÉINITIALISER </span>       <span style="background-color:grey;color:white;">  SAUVER </span>  </p></div><p>Lorsque plusieurs types d&#39;insuline sont configurés, l&#39;utilisation des <a href="./mainUI.html#treatments">traitements</a> vous demandera de choisir celui que vous utilisez pour ce traitement.</p><img src="'+m+'" style="zoom:75%;"><p>Vous pouvez ajouter l&#39;insuline basale à l&#39;affichage et l&#39;intégrer au calcul.<br> Ce n&#39;est pas recommandé, car en multi-injections l&#39;insuline basale sert seulement à maintenir une glycémie de fond constante.<br> Utilisez les <a href="./mainUI.html#treatment-notes">notes</a> pour suivre les injections de basale.</p><p>Les différents types d&#39;insuline s&#39;affichent de façon identique sur le graphique principal.</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser l&#39;activité Basal</p><p> Tracer l&#39;activité basale sur le graphique et l&#39;incorporer dans le modèle prédictif</p></div><img src="'+b+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',80)])])}const N=f(_,[["render",x]]);export{T as __pageData,N as default};
